def transform(grid):
    # Fill enclosed background cells (not reachable from the border without crossing wall cells)
    h, w = len(grid), len(grid[0])
    wall = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    # In these puzzles the sparse non-background color forms the boundary.
    colors = {x for row in grid for x in row}
    bg = wall
    line = min(colors, key=lambda c: sum(row.count(c) for row in grid))
    fill = next((c for c in range(10) if c not in colors), 3)
    seen=set()
    stack=[]
    for r in range(h):
        for c in range(w):
            if r in (0,h-1) or c in (0,w-1):
                if grid[r][c] != line and (r,c) not in seen:
                    seen.add((r,c)); stack.append((r,c))
    while stack:
        r,c=stack.pop()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=line and (rr,cc) not in seen:
                seen.add((rr,cc)); stack.append((rr,cc))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=line and (r,c) not in seen: out[r][c]=fill
    return out
